contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        // drive c through a public entry point that pushes past paused-checking
        // into a state change (deposit reads a token address, so pick the
        // collateral token address from the public data() getter).
        DataView memory d = c.data();

        bool depositReverted;
        try c.deposit{value: 0}(DepositParams({token: address(d.underlyingCollateralToken), amount: amount, to: address(this)})) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // whichever branch we took, the public paused() view must still report false
        bool pausedNow = c.paused();

        assert(pausedNow == false);
    }

    receive() external payable {}
}

