contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address owner, bytes32 role, address account) public payable {
        require(role != bytes32(0));

        address caller = address(this);

        bool hasRoleBefore = c.hasRole(role, caller);
        bytes32 adminRole = c.getRoleAdmin(role);
        bool canManage = c.hasRole(adminRole, caller);
        bool reverted;
        if (canManage) {
            try c.grantRole(role, account) {
                reverted = false;
            } catch {
                reverted = true;
            }
            bool hasRoleAfterGrant = c.hasRole(role, account);
            assert(!reverted && hasRoleAfterGrant);
        } else {
            try c.grantRole(role, account) {
                reverted = false;
            } catch {
                reverted = true;
            }
            bool hasRoleAfterGrant = c.hasRole(role, account);
            assert(!reverted && hasRoleAfterGrant == hasRoleBefore);
        }
    }
}

